-- Extend only the visual allowlist. No new tables, grants or authorization changes.
begin;
create or replace function private.totus_validate_appearance(p_section text,p_config jsonb) returns void language plpgsql security invoker set search_path='' as $$
declare schema jsonb='{"interfaz":{"navigationMode":{"type":"select","options":["expanded","compact"]},"startModule":{"type":"select","options":["inicio","pricing","cajas","gastos","facturacion","cotejos","tareas","equipo","documentos","fiscalidad","informes","administracion","configuracion"]},"brandName":{"type":"text","max":32},"brandSubtitle":{"type":"text","max":90},"logoMode":{"type":"select","options":["tf","hortimatic","newoldsmok","uploaded"]},"customLogoData":{"type":"image","max":350000},"logoHeight":{"type":"range","min":28,"max":64},"backgroundMode":{"type":"select","options":["color","image"]},"customBackgroundData":{"type":"image","max":350000},"backgroundDim":{"type":"range","min":0,"max":90},"theme":{"type":"select","options":["light","dark"]},"primary":{"type":"color"},"secondary":{"type":"color"},"accent":{"type":"color"},"bg":{"type":"color"},"surface":{"type":"color"},"card":{"type":"color"},"text":{"type":"color"},"muted":{"type":"color"},"density":{"type":"select","options":["compact","comfortable","wide"]},"shadow":{"type":"select","options":["none","soft","strong"]},"sidebarWidth":{"type":"range","min":240,"max":330},"topbarHeight":{"type":"range","min":56,"max":88},"fontSize":{"type":"range","min":13,"max":16},"pagePad":{"type":"range","min":12,"max":36},"gap":{"type":"range","min":8,"max":28},"radius":{"type":"range","min":8,"max":28},"buttonRadius":{"type":"range","min":6,"max":24},"cardPadding":{"type":"range","min":12,"max":24},"tableRowHeight":{"type":"range","min":34,"max":52},"borderStrength":{"type":"range","min":6,"max":24},"borderColor":{"type":"color"},"borderWidth":{"type":"range","min":0,"max":3},"glowColor":{"type":"color"},"cardGlow":{"type":"range","min":0,"max":24},"buttonGlow":{"type":"range","min":0,"max":24},"hoverEffect":{"type":"select","options":["none","lift","glow"]},"buttonFinish":{"type":"select","options":["flat","gradient","gloss"]},"buttonStyle":{"type":"select","options":["rounded","soft"]}},"login":{"loginBrandName":{"type":"text","max":36},"loginSubtitle":{"type":"text","max":86},"loginFont":{"type":"select","options":["system","rounded","serif","mono"]},"loginLogoMode":{"type":"select","options":["mark","text","uploaded"]},"loginLogoFrame":{"type":"select","options":["none","soft"]},"loginLogoWidth":{"type":"range","min":48,"max":100},"loginLogoHeight":{"type":"range","min":42,"max":110},"loginAlign":{"type":"select","options":["left","center"]},"customLogoData":{"type":"image","max":350000},"loginCardPreset":{"type":"select","options":["solid","transparent","glass","dark","light"]},"loginCardColor":{"type":"color"},"loginCardOpacity":{"type":"range","min":45,"max":100},"loginCardRadius":{"type":"range","min":10,"max":34},"loginCardShadow":{"type":"select","options":["none","soft","strong"]},"loginButtonMode":{"type":"select","options":["gradient","solid","outline"]},"loginButtonColor":{"type":"color"},"loginTextColor":{"type":"color"},"loginBorderColor":{"type":"color"},"loginCardWidth":{"type":"range","min":360,"max":520},"loginCardPadding":{"type":"range","min":18,"max":36},"loginBackground":{"type":"select","options":["dark-gradient","light-clean","totus-corporate","tech-soft","gold-night","uploaded"]},"loginBorderWidth":{"type":"range","min":0,"max":3},"loginGlowColor":{"type":"color"},"loginCardGlow":{"type":"range","min":0,"max":24},"loginButtonGlow":{"type":"range","min":0,"max":24},"loginBackgroundDim":{"type":"range","min":0,"max":80},"customBackgroundData":{"type":"image","max":350000},"loginHelpText":{"type":"text","max":180},"loginRecoveryText":{"type":"text","max":80}}}'::jsonb; pair record; rule jsonb;
begin
 if p_section is null or not schema?p_section then raise exception 'Sección no válida.';end if;
 if p_config is null or jsonb_typeof(p_config)<>'object' or octet_length(p_config::text)>760000 then raise exception 'Configuración no válida.';end if;
 for pair in select * from jsonb_each(p_config) loop
  rule=schema->p_section->pair.key;
  if rule is null then raise exception 'Campo de apariencia no válido: %',pair.key;end if;
  if rule->>'type'='range' then
   if jsonb_typeof(pair.value)<>'number' then raise exception 'Valor numérico no válido.';end if;
   if (pair.value#>>'{}')::numeric not between (rule->>'min')::numeric and (rule->>'max')::numeric then raise exception 'Valor fuera de rango.';end if;
  else
   if jsonb_typeof(pair.value)<>'string' then raise exception 'Texto no válido.';end if;
   if rule->>'type'='color' and (pair.value#>>'{}') !~ '^#[0-9a-fA-F]{6}$' then raise exception 'Color no válido.';end if;
   if rule->>'type'='select' and not (rule->'options')?(pair.value#>>'{}') then raise exception 'Opción no válida.';end if;
   if rule->>'type'='text' and length(pair.value#>>'{}')>(rule->>'max')::integer then raise exception 'Texto demasiado largo.';end if;
   if rule->>'type'='image' and (length(pair.value#>>'{}')>350000 or ((pair.value#>>'{}')<>'' and (pair.value#>>'{}') !~ '^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/]+=*$')) then raise exception 'Imagen no válida.';end if;
  end if;
 end loop;
 if p_section='interfaz' and ((p_config->>'logoMode'='uploaded' and coalesce(p_config->>'customLogoData','')='') or (p_config->>'backgroundMode'='image' and coalesce(p_config->>'customBackgroundData','')='')) then raise exception 'Selecciona la imagen de marca.';end if;
 if p_section='login' and ((p_config->>'loginLogoMode'='uploaded' and coalesce(p_config->>'customLogoData','')='') or (p_config->>'loginBackground'='uploaded' and coalesce(p_config->>'customBackgroundData','')='')) then raise exception 'Selecciona la imagen de marca.';end if;

end $$;
revoke all on function private.totus_validate_appearance(text,jsonb) from public,anon,authenticated;
commit;
